const periodData=()=>{const data=PERIODS[state.period];if(state.dir==='all')return {...data};const shares={service:.5,ecosystem:.34,foundation:.16};const factor=shares[state.dir];return {...data,reached:Math.round(data.reached*factor),active:Math.round(data.active*factor),served:Math.round(data.served*factor),reused:Math.round(data.reused*factor),series:data.series.map(x=>Math.round(x*factor)),served_series:data.served_series.map(x=>Math.round(x*factor))}};
const context=()=>`<div class="context-strip"><span class="evidence-tag">演示快照</span><span>${state.dir==='all'?'全部战略方向':DIRECTIONS[state.dir].name}</span><span>·</span><span>${PERIODS[state.period].label}</span><span>·</span><span>建设状态为期末存量，用户指标为本期去重</span></div>`;
const head=(title,sub,action='',target='')=>`<div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action?`<button class="panel-action" data-action="${target}">${action} ↗</button>`:''}</div>`;
function spark(color='8ba7dc'){return `<svg class="metric-spark" viewBox="0 0 70 30" aria-hidden="true"><path d="M0 27 8 24 15 26 24 18 33 20 42 12 50 15 61 5 70 2" fill="none" stroke="#${color}" stroke-width="1.5"/><path d="M0 27 8 24 15 26 24 18 33 20 42 12 50 15 61 5 70 2v28H0Z" fill="#${color}" opacity=".07"/></svg>`}
function metric(title,value,unit,sub,change,action,color){return `<button class="panel metric-card" data-action="${action}"><div class="metric-top"><span>${title}</span><span class="metric-icon">↗</span></div><div class="metric-number">${value}<small>${unit}</small></div><div class="metric-bottom"><span class="positive">${change}</span><span>${sub}</span></div>${spark(color)}</button>`}
function lanePanel(){return `<section class="panel">${head('三条战略主线','目标、建设与下一关，保持同一条路径','查看产品组合','goto:projects')}<div class="lane-list">${Object.entries(DIRECTIONS).filter(([k])=>state.dir==='all'||state.dir===k).map(([key,d])=>{let ps=PROJECTS.filter(p=>p.dir===key),avg=Math.round(ps.reduce((a,p)=>a+p.delivery,0)/ps.length);return `<button class="lane" data-action="direction:${key}"><div class="lane-icon ${d.color}">${d.icon}</div><div><div class="lane-title">${d.name}<span>${ps.length} 个项目</span></div><div class="lane-desc">${d.next}</div><div class="progress-track ${d.color}"><span style="width:${avg}%"></span></div></div><div class="lane-value">${avg}<span style="font-size:10px">%</span><small>建设完成度</small></div></button>`}).join('')}</div></section>`}
function scatter(){const color={service:'#7b97d2',ecosystem:'#80a998',foundation:'#c5ad77'};return `<section class="panel">${head('建设与价值验证','项目在两个维度上的阶段位置','查看阶段定义','help')}<div class="scatter-wrap"><svg class="chart-svg" viewBox="0 0 390 204" role="img" aria-label="项目建设完成度与价值验证位置"><rect x="46" y="15" width="317" height="150" rx="3" fill="#f8f9fc"/><rect x="205" y="15" width="158" height="75" fill="#eef5ef"/><path d="M46 15v150h317" fill="none" stroke="#dbe2ec"/><path d="M46 90h317M205 15v150" stroke="#dfe5ef" stroke-dasharray="3 4"/><text x="56" y="31" font-size="8" fill="#a4aebd">价值先行</text><text x="288" y="31" font-size="8" fill="#a3b5a6">规模复用</text><text x="56" y="153" font-size="8" fill="#a4aebd">探索验证</text><text x="288" y="153" font-size="8" fill="#a4aebd">待验价值</text><text x="205" y="192" text-anchor="middle" font-size="9" fill="#9ca6b6">交付成熟度 →</text><text transform="translate(17,92) rotate(-90)" text-anchor="middle" font-size="9" fill="#9ca6b6">价值验证 →</text>${currentProjects().map(p=>{let x=46+p.delivery*3.17,y=165-p.validation*1.5;return `<g class="scatter-point" tabindex="0" role="button" aria-label="${esc(p.name)}，查看项目" data-action="project:${p.id}"><circle cx="${x}" cy="${y}" r="6" fill="${color[p.dir]}" fill-opacity=".85"/><text x="${x+9}" y="${y+3}" font-size="8" fill="#7c8ea7">${p.id}</text></g>`}).join('')}</svg><div class="scatter-legend">${Object.entries(DIRECTIONS).map(([k,d])=>`<span><i class="legend-dot" style="background:${color[k]}"></i>${d.short}</span>`).join('')}</div></div></section>`}
function trendChart(){const d=periodData(),w=530,h=163,left=35,right=13,top=10,bottom=30,max=Math.max(1000,Math.ceil(Math.max(...d.series)*1.12/1000)*1000);const pt=(v,i)=>[left+i*(w-left-right)/5,top+(1-v/max)*(h-top-bottom)];const line=d.series.map((v,i)=>pt(v,i).join(',')).join(' ');const area=`${left},${h-bottom} ${line} ${w-right},${h-bottom}`;return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${d.short}活跃与有效服务用户趋势，演示数据"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#8eaae3" stop-opacity=".18"/><stop offset="1" stop-color="#8eaae3" stop-opacity="0"/></linearGradient></defs>${[0,.5,1].map(r=>`<path d="M${left} ${top+r*(h-top-bottom)}H${w-right}" stroke="#edf1f7" stroke-dasharray="3 3"/><text x="${left-8}" y="${top+r*(h-top-bottom)+3}" text-anchor="end" font-size="8" fill="#aab4c3">${Math.round(max*(1-r)/1000)}k</text>`).join('')}<polygon points="${area}" fill="url(#chart-fill)"/><polyline points="${line}" fill="none" stroke="#7b98d5" stroke-width="2"/><polyline points="${d.served_series.map((v,i)=>pt(v,i).join(',')).join(' ')}" fill="none" stroke="#8db4a0" stroke-width="1.8"/>${d.ticks.map((t,i)=>`<text x="${pt(0,i)[0]}" y="${h-10}" text-anchor="middle" font-size="8" fill="#a0aabd">${t}</text>`).join('')}${d.series.map((v,i)=>`<circle data-chart-tip="${d.ticks[i]} · 活跃用户 ${fmt(v)} 人（演示）" tabindex="0" cx="${pt(v,i)[0]}" cy="${pt(v,i)[1]}" r="2.5" fill="white" stroke="#7b98d5" stroke-width="1.5"/>`).join('')}</svg>`}
function miniProject(p){return `<button class="panel project-mini" data-action="project:${p.id}"><div class="project-mini-top"><span>${p.id} / ${DIRECTIONS[p.dir].name}</span>${tag(p.status)}</div><h3>${esc(p.name)}</h3><p>${esc(p.next)}</p><div class="progress-track"><span style="width:${p.delivery}%"></span></div><div class="project-mini-bottom"><span>下一关 ${esc(projectDate(p))}</span><span>${p.delivery}% <span style="color:#c1c8d3"> / 建设</span></span></div></button>`}
function overview(){const d=periodData(),ps=currentProjects(),next=ps.filter(p=>p.status!=='按计划').slice(0,3),entrances=relevantEntrances().filter(e=>e.status==='生产上架');return `<section class="hero"><div><div class="hero-kicker"><span class="live-dot"></span>${d.short} 管理判断 <span style="opacity:.6">/ 演示汇报</span></div><h2>${state.dir==='all'?'让 AI 能力，形成持续的业务价值':DIRECTIONS[state.dir].goal}</h2><p>建设正从能力与入口覆盖，进入任务闭环和规模复用。当前应优先补齐用户归因、机构验收与持续运营证据，让每项进展都有下一关。</p></div><div class="hero-aside"><div class="label">本期管理焦点 / NEXT GATE</div><h3>统一数据口径，推进关键场景验收</h3><p>资源集中在可验证的服务任务与机构试点。</p><button data-action="goto:roadmap">查看问题与决策 <span>↗</span></button></div></section><div class="metric-grid">${metric('推进中项目',ps.length,'个','项目组合','期末存量','goto:projects','97abc8')}${metric('有效服务用户',fmt(d.served),'人','较上个等长窗口',d.growth,'goto:impact','7da68e')}${metric('可复用 Skills',relevantCaps().reduce((a,c)=>a+c[2],0),'项','能力目录','期末存量','goto:capabilities','8b9bc0')}${metric('生产上架入口',entrances.length,'个',`共 ${relevantEntrances().length} 个接入入口`,'期末存量','goto:ecosystem','baa676')}</div><div class="grid-2">${lanePanel()}${scatter()}</div><div class="grid-2"><section class="panel">${head('用户价值趋势','同一用户实体下的活跃与有效服务','查看用户分析','goto:impact')}<div class="compact-chart"><div class="chart-legend"><span><i class="legend-dot" style="background:#7b98d5"></i>活跃用户</span><span><i class="legend-dot" style="background:#8db4a0"></i>有效服务用户</span></div>${trendChart()}<div class="mini-note">演示数据 · 趋势为截至当日的窗口累计去重；不代表真实业务数据。</div></div></section><section class="panel">${head('本期需要推进的决定','问题、影响与下一步放在同一张卡片里','全部决策','issues')}<div class="decision-list">${ISSUES.filter(x=>state.dir==='all'||PROJECTS.find(p=>p.id===x.project).dir===state.dir).slice(0,3).map((x,i)=>`<button class="decision-row" data-action="project:${x.project}"><span class="decision-number">0${i+1}</span><div class="decision-content"><h3>${x.title}</h3><p>${x.owner} · 目标 ${x.date}</p></div><span class="decision-meta">${x.severity}</span></button>`).join('')||'<div class="empty-state">当前方向没有待推进决策</div>'}</div></section></div><div class="section-head"><div><h2>关键项目 · 下一里程碑</h2><p style="margin-top:4px">把计划写成可验收的下一步</p></div><button class="panel-action" data-action="goto:projects">全部项目 ↗</button></div><div class="project-mini-grid">${(next.length?next:ps.slice(0,3)).map(miniProject).join('')}</div>${window.CockpitUpdates?window.CockpitUpdates.renderHighlights(4):''}`}
function projectCard(p){return `<button class="panel project-card" data-action="project:${p.id}"><div class="project-mini-top"><span>${p.id} / ${DIRECTIONS[p.dir].name}</span>${tag(p.status)}</div><h3>${esc(p.name)}</h3><p class="project-desc">${esc(p.desc)}</p><div class="tags">${tag(p.deliveryLabel,'blue')}${tag(p.valueLabel,'gray')}</div><div class="stage-pair"><div><small>交付成熟度</small><span>${p.delivery}%</span><div class="progress-track" style="margin-top:8px"><span style="width:${p.delivery}%"></span></div></div><div><small>价值验证</small><span>${p.validation}%</span><div class="progress-track green" style="margin-top:8px"><span style="width:${p.validation}%"></span></div></div></div><div class="project-next"><b>下一步</b> ${esc(p.next)}</div><div class="project-mini-bottom"><span>${esc(p.owner)}</span><span>目标 ${esc(projectDate(p))} ↗</span></div></button>`}
function projectTable(ps){return `<section class="panel table-scroll"><table class="data-table"><thead><tr><th>产品 / 项目</th><th>战略方向</th><th>状态</th><th>交付 / 价值验证</th><th>下一里程碑</th><th>负责团队</th></tr></thead><tbody>${ps.map(p=>`<tr tabindex="0" data-action="project:${p.id}"><td class="table-title">${esc(p.name)}<small>${p.id} · ${p.deliveryLabel}</small></td><td>${DIRECTIONS[p.dir].name}</td><td>${tag(p.status)}</td><td>${p.delivery}% <span style="color:#b4c0d2"> / </span>${p.validation}%</td><td>${esc(projectDate(p))} ${p.next.slice(0,13)}…</td><td>${esc(p.owner)} ↗</td></tr>`).join('')}</tbody></table></section>`}
function milestones(ps){return `<section class="panel table-scroll"><table class="data-table"><thead><tr><th>项目</th><th>里程碑</th><th>目标日期</th><th>验收条件</th><th>依赖 / 卡点</th></tr></thead><tbody>${ps.map(p=>`<tr tabindex="0" data-action="project:${p.id}"><td class="table-title">${esc(p.name)}<small>${p.id}</small></td><td>${p.history.at(-1)[2]}</td><td>${esc(projectDate(p))}</td><td>${esc(p.next)}</td><td>${tag(p.status)} ${p.issue.slice(0,14)}…</td></tr>`).join('')}</tbody></table></section>`}
function projects(){let ps=relevantProjects();return `${context()}<div class="project-tools"><div class="segmented"><button data-action="projectmode:cards" class="${state.projectMode==='cards'?'selected':''}">产品卡片</button><button data-action="projectmode:table" class="${state.projectMode==='table'?'selected':''}">项目台账</button><button data-action="projectmode:milestones" class="${state.projectMode==='milestones'?'selected':''}">里程碑颗粒度</button></div><div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><span class="count-text">${ps.length} 个项目</span><select id="status-filter" aria-label="项目状态"><option value="all">全部状态</option>${['按计划','需关注','待决策','规划中'].map(s=>`<option value="${s}" ${state.status===s?'selected':''}>${s}</option>`).join('')}</select><input class="search-input" id="project-search" placeholder="搜索项目、编号或团队" value="${esc(state.search)}" aria-label="搜索项目"></div></div>${ps.length?(state.projectMode==='cards'?`<div class="project-grid">${ps.map(projectCard).join('')}</div>`:state.projectMode==='table'?projectTable(ps):milestones(ps)):'<div class="panel empty-state">没有匹配项目，可调整搜索词或筛选条件。</div>'}<div class="callout"><b>统一项目档案</b> · 每个项目均包含目标、建设历程、当前交付、价值证据、问题、下一步与待决策。交付成熟度和价值验证为独立阶段映射分值，原型中用于展示结构。</div>`}
function impact(){const d=periodData(),rows=state.impactGrain==='channel'?[['自营服务',.5],['外部平台',.27],['机构入口',.17],['其他入口',.06]]:state.impactGrain==='cohort'?[['新用户',.46],['近 30 天老用户',.35],['长期用户',.19]]:[['任务规划',.38],['分析解释',.34],['持续陪伴',.28]];return `${context()}<section class="panel">${head('从使用到结果，观察服务的每一关','以下为同一统计窗口与统一用户 ID 下的演示队列','指标口径','help')}<div class="funnel">${[['到达用户',d.reached,100,'到达服务入口'],['活跃用户',d.active,Math.round((d.reached?d.active/d.reached:0)*100),'产生主动服务行为'],['有效服务用户',d.served,Math.round((d.reached?d.served/d.reached:0)*100),'至少完成 1 个有效任务'],['7 日复用用户',d.reused,Math.round((d.reached?d.reused/d.reached:0)*100),'有效服务后 7 日内再次完成任务']].map(([t,v,w,s])=>`<div class="funnel-step"><h3>${t}</h3><strong>${fmt(v)}</strong><small>${s}</small><div class="funnel-bar"><span style="width:${w}%"></span></div></div>`).join('')}</div></section><div class="callout"><b>队列口径</b> · 7 日复用仅统计已满 7 日观察期的有效服务用户。演示中可观察队列为 ${fmt(Math.round(d.served*.8))} 人，复用率为 ${((Math.round(d.served*.8)?d.reused/Math.round(d.served*.8):0)*100).toFixed(1)}%。跨平台用户仅在身份可核对时去重。</div><div class="grid-2"><section class="panel">${head('用户增长与有效服务','按当前周期展示窗口累计去重')}<div class="compact-chart"><div class="chart-legend"><span><i class="legend-dot" style="background:#7b98d5"></i>活跃用户</span><span><i class="legend-dot" style="background:#8db4a0"></i>有效服务用户</span></div>${trendChart()}<div class="trend-caption"><span>有效服务占活跃用户 <b>${((d.active?d.served/d.active:0)*100).toFixed(1)}%</b></span><span>统计至 10.27 · 演示</span></div></div></section><section class="panel">${head('服务质量与数据完整性','质量、效果与证据覆盖分别观察')}<div class="quality-rows"><button class="quality-row" data-action="help" style="width:100%"><span>有效任务完成率</span><b>86.4<small>%</small></b></button><button class="quality-row" data-action="project:P08" style="width:100%"><span>服务一次成功率</span><b>94.2<small>%</small></b></button><button class="quality-row" data-action="project:P07" style="width:100%"><span>核心事件覆盖率</span><b>78.0<small>%</small></b></button><button class="quality-row" data-action="project:P07" style="width:100%"><span>跨端身份可核对率</span><b style="color:#b69b62">62.0<small>%</small></b></button></div></section></div><section class="panel">${head('拆开维度，找到增长与流失的位置','分组数值均来自同一演示队列')}<div class="project-tools" style="padding:18px 22px 0;margin-bottom:12px"><div class="segmented">${[['channel','按渠道'],['cohort','按客群'],['task','按任务']].map(([k,t])=>`<button data-action="impactgrain:${k}" class="${state.impactGrain===k?'selected':''}">${t}</button>`).join('')}</div><span class="count-text">${state.dir==='all'?'全部战略方向':DIRECTIONS[state.dir].name}</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>分组</th><th>活跃用户</th><th>有效服务用户</th><th>有效服务率</th><th>7 日复用用户</th><th>证据状态</th></tr></thead><tbody>${rows.map(([t,n])=>`<tr tabindex="0" data-action="help"><td class="table-title">${t}</td><td>${fmt(Math.round(d.active*n))}</td><td>${fmt(Math.round(d.served*n))}</td><td>${((d.active?d.served/d.active:0)*100).toFixed(1)}%</td><td>${fmt(Math.round(d.reused*n))}</td><td>${tag('演示数据','gray')} ↗</td></tr>`).join('')}</tbody></table></div></section>`}
function capabilities(){const cs=relevantCaps(),tot=[1,2,3].map(i=>cs.reduce((a,c)=>a+c[i],0));const levels=[['MCP','标准数据与工具','可调用、可授权的底层能力',tot[0],'能力供给'],['Skills','可复用任务方法','有输入、步骤与输出的专业任务',tot[1],'任务复用'],['Agents','连续服务与编排','面向目标、具备状态的服务单元',tot[2],'服务闭环']];return `${context()}<div class="capability-stack">${levels.map((x,i)=>`<button class="panel stack-card" data-action="caplevel:${i+1}"><div class="stack-level">LAYER 0${i+1}</div><h2 class="stack-name">${x[0]}</h2><p>${x[1]}</p><div class="stack-count">${x[3]}<small>项 · 演示</small></div><div class="stack-meta"><span>${x[4]}</span><span>查看能力域 ↗</span></div></button>`).join('')}</div><section class="panel">${head('能力资产 × 业务场景','点击能力域查看关联项目、维护责任与质量证据','资产口径','help')}<div class="project-tools" style="padding:17px 22px 0"><div class="segmented">${[['all','全部能力'],['1','MCP'],['2','Skills'],['3','Agents']].map(([k,t])=>`<button data-action="caplevel:${k}" class="${String(state.capLevel)===k?'selected':''}">${t}</button>`).join('')}</div><div class="small-legend"><span><i class="heatmap-dot full"></i>主用</span><span><i class="heatmap-dot partial"></i>复用</span><span><i class="heatmap-dot"></i>待拓展</span></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>能力域</th>${state.capLevel==='all'?'<th>MCP</th><th>Skills</th><th>Agents</th>':`<th>${levels[Number(state.capLevel)-1][0]} 数量</th>`}<th>自营服务</th><th>外部生态</th><th>治理底座</th><th>资产状态</th></tr></thead><tbody>${cs.filter(c=>state.capLevel==='all'||c[Number(state.capLevel)]>0).map((c,i)=>`<tr tabindex="0" data-action="cap:${CAPABILITIES.indexOf(c)}"><td class="table-title">${c[0]}<small>${c[4]}</small></td>${state.capLevel==='all'?`<td>${c[1]}</td><td>${c[2]}</td><td>${c[3]}</td>`:`<td>${c[Number(state.capLevel)]}</td>`}${[0,1,2].map(j=>`<td><span class="heatmap-dot ${j===i%3?'full':(j+i)%2?'partial':''}"></span></td>`).join('')}<td>${tag(c[6])} ↗</td></tr>`).join('')}</tbody></table></div></section><div class="grid-equal" style="margin-top:20px"><section class="panel">${head('资产生命周期','每项能力具备独立的版本、责任与证据')}<div class="timeline">${[['定义','目标用户、输入输出、权限与依赖'],['验证','评测样本、异常路径与验收证据'],['发布','版本、维护责任与回滚机制'],['运营','成功使用、复用关系与退役判断']].map((x,i)=>`<div class="timeline-item"><div class="timeline-date">0${i+1} / ${x[0]}</div><h3>${x[1]}</h3></div>`).join('')}</div></section><section class="panel">${head('能力盘点的下一步','从有多少项，推进到每一项是否可交付')}<div class="decision-list">${[['维护责任','补齐资产负责人、版本与依赖','P04'],['质量证据','绑定评测集、成功记录与异常处理','P08'],['结果连接','连接项目、入口、用户任务与成效','P07']].map((x,i)=>`<button class="decision-row" data-action="project:${x[2]}"><span class="decision-number">0${i+1}</span><div class="decision-content"><h3>${x[0]}</h3><p>${x[1]}</p></div><span>↗</span></button>`).join('')}</div></section></div>`}
const cooperationStages=['意向探索','方案对齐','联调验收','联合试点','规模推广','持续运营'];
function orgCard(o){return `<button class="panel org-card" data-action="org:${o.id}"><div class="org-header"><span class="org-logo">${o.name.slice(-1)}</span><div><h3>${o.name}</h3><p>${o.type} · ${o.id}</p></div><span style="margin-left:auto">${tag(o.stage)}</span></div><div class="stage-pair"><div><small>合作方式</small><span>${o.mode}</span></div><div><small>商业阶段</small><span>${o.commercial}</span></div></div><div class="org-progress">${cooperationStages.map((s,i)=>`<span class="${i<=o.step?'done':''}"></span>`).join('')}</div><div class="org-card-bottom"><span>${o.next}</span><span>详情 ↗</span></div></button>`}
function orgMatrix(os){return `<section class="panel table-scroll"><table class="data-table"><thead><tr><th>合作机构</th><th>合作方式</th><th>交付阶段</th><th>商业阶段</th><th>当前问题</th><th>下一步</th></tr></thead><tbody>${os.map(o=>`<tr tabindex="0" data-action="org:${o.id}"><td class="table-title">${o.name}<small>${o.type} / ${o.id}</small></td><td>${o.mode}</td><td>${tag(o.stage)}</td><td>${o.commercial}</td><td>${o.block.slice(0,15)}…</td><td>${o.next} ↗</td></tr>`).join('')}</tbody></table></section>`}
function ecosystem(){const os=relevantOrgs(),es=relevantEntrances();return `${context()}<div class="subnav"><button data-action="ecotab:partners" class="${state.ecoTab==='partners'?'active':''}">机构合作 <span style="opacity:.6">${os.length}</span></button><button data-action="ecotab:listings" class="${state.ecoTab==='listings'?'active':''}">外部上架 <span style="opacity:.6">${es.length}</span></button></div>${state.ecoTab==='partners'?`<div class="project-tools"><div class="segmented"><button data-action="orgmode:matrix" class="${state.orgMode==='matrix'?'selected':''}">合作矩阵</button><button data-action="orgmode:cards" class="${state.orgMode==='cards'?'selected':''}">机构卡片</button></div><div style="display:flex;gap:10px;flex-wrap:wrap"><select id="cooperation-filter" aria-label="合作方式"><option value="all">全部合作方式</option>${[...new Set(ORGS.map(o=>o.mode))].map(s=>`<option ${state.orgModeFilter===s?'selected':''}>${s}</option>`).join('')}</select><input id="org-search" class="search-input" placeholder="搜索机构或机构类型" aria-label="搜索机构" value="${esc(state.orgSearch)}"></div></div>${!os.length?'<div class="panel empty-state">当前条件下没有合作机构。</div>':state.orgMode==='cards'?`<div class="org-grid">${os.map(orgCard).join('')}</div>`:orgMatrix(os)}<div class="callout"><b>合作管理模型</b> · 同一家机构可关联多个入口、合作方式与交付范围。每条合作关系独立记录交付阶段、合同、验收、开票与回款证据；未知保留“尚未确认”。本原型机构全部匿名演示。</div>`:`<div class="listing-grid">${es.map(e=>`<button class="panel listing-card" data-action="entrance:${e.id}"><div class="listing-symbol">${e.id.slice(-2)}</div>${tag(e.status)}<h3>${e.name}</h3><p>${e.type} · ${e.protocol}<br>${e.health}</p><div class="listing-meta"><span>${e.version}</span><span>查看上架档案 ↗</span></div></button>`).join('')||'<div class="panel empty-state">当前战略方向没有接入入口。</div>'}</div><section class="panel">${head('上架生命周期','每个入口都需要版本、巡检与服务后结果')}<div class="funnel">${[['适配','接口协议与权限边界'],['联调','端到端任务与事件验收'],['上架','版本记录与可用性巡检'],['运营','用户使用、服务结果与复用']].map(([t,s],i)=>`<div class="funnel-step"><h3>0${i+1}</h3><strong style="font-size:20px">${t}</strong><small>${s}</small></div>`).join('')}</div></section><div class="callout"><b>上架证据</b> · 正式接入时保存平台页面、发布版本、验收记录、最近巡检时间和任务结果。一个机构的多种合作关系分别关联入口，避免把机构数、合作数和上架数混为同一指标。</div>`}`}
function issuesView(){const is=ISSUES.filter(x=>state.dir==='all'||PROJECTS.find(p=>p.id===x.project).dir===state.dir);return `<div class="issue-grid">${is.map(x=>`<button class="panel issue-card" style="text-align:left" data-action="project:${x.project}">${tag(x.severity,x.color)}<h3>${x.title}</h3><p>${x.impact}</p><p style="margin-top:11px;color:#6c829f"><b style="font-weight:500">需要决定</b> · ${x.decision}</p><div class="issue-meta"><span>${x.owner}</span><span>目标 ${x.date} ↗</span></div></button>`).join('')||'<div class="panel empty-state">当前方向暂无演示问题。</div>'}</div>`}
function roadmap(){return `${context()}<div class="subnav">${[['roadmap','季度路线'],['timeline','事件时间表'],['history','建设历程'],['issues','问题与决策']].map(([k,t])=>`<button data-action="roadtab:${k}" class="${state.roadTab===k?'active':''}">${t}${k==='issues'?` <span style="opacity:.6">${ISSUES.filter(x=>state.dir==='all'||PROJECTS.find(p=>p.id===x.project).dir===state.dir).length}</span>`:''}</button>`).join('')}</div>${state.roadTab==='timeline'?(window.CockpitUpdates?window.CockpitUpdates.renderTimeline():''):state.roadTab==='issues'?issuesView():state.roadTab==='history'?`<section class="panel">${head('从机会识别，走向价值验证','历史为冻结的演示记录；正式接入时以事件与证据为准')}<div class="timeline">${[['2026.07','确定战略主线与能力结构','形成自营服务、开放生态、共用治理的建设路径。','P04'],['2026.08','建立标准能力与合作路径','整理能力目录、接口规范和机构接入方案。','P04'],['2026.09','开展场景与外部入口验证','进入服务试点、入口联调和机构方案对齐。','P05'],['2026.10','从建设覆盖推进到任务闭环','重点补齐用户归因、持续使用与机构验收证据。','P07'],['2026.11 · 计划','完成关键验收与质量门槛','统一事件口径，复核重点任务，推进机构试点验收。','P06'],['2026.12 · 计划','复盘有效场景，决定规模投入','按复用、稳定性和任务结果调整下季度资源。','P02']].filter(x=>state.dir==='all'||PROJECTS.find(p=>p.id===x[3]).dir===state.dir).map(x=>`<div class="timeline-item"><div class="timeline-date">${x[0]}</div><button style="padding:0;text-align:left" data-action="project:${x[3]}"><h3>${x[1]} ↗</h3><p>${x[2]}</p></button></div>`).join('')}</div></section>`:`<section class="panel">${head('建设路径与下一关','先建立基础，再形成闭环，最后决定如何规模复用')}<div class="roadmap table-scroll"><div class="roadmap-header"><span>战略方向</span><span>10 月 · 建设与试点</span><span>11 月 · 闭环与验收</span><span>12 月 · 复用与复盘</span><span>下一季 · 规模决策</span></div>${Object.entries(DIRECTIONS).filter(([k])=>state.dir==='all'||state.dir===k).map(([k,d])=>{let items=k==='service'?[['重点场景试点','任务定义与首轮验证','P02'],['核心服务闭环','跨端任务与结果验收','P01'],['持续服务复用','复核任务完成与复用','P01'],['扩展优质场景','按验证结果选择投入','P02']]:k==='ecosystem'?[['入口与目录标准化','能力目录、上架规范','P04'],['机构试点验收','范围、责任与证据','P06'],['联合运营复盘','入口效果与机构复用','P05'],['复制接入模式','形成标准交付包','P06']]:[['统一数据与治理','事件、身份与评测','P07'],['关键链路验收','数据覆盖与权限检查','P07'],['质量与回滚演练','异常处理和责任闭环','P08'],['规模治理门槛','发布质量与服务稳定','P08']];return `<div class="roadmap-row"><div class="roadmap-label">${d.name}<small>${d.next}</small></div>${items.map(x=>`<div class="roadmap-cell"><button class="roadmap-task ${d.color==='blue'?'':d.color}" data-action="project:${x[2]}">${x[0]}<small>${x[1]} ↗</small></button></div>`).join('')}</div>`}).join('')}</div></section><div class="callout"><b>路线规划原则</b> · 每一阶段绑定可验收成果、负责团队与依赖。计划与实际分别保存；进入下一阶段前复核用户证据、机构验收与质量门槛。</div><div class="section-head"><h2>最近需要推进的决定</h2><button class="panel-action" data-action="issues">查看全部 ↗</button></div>${issuesView()}`}`}
function render(){const v=NAV.find(x=>x[0]===state.view)||NAV[0];document.getElementById('navigation').innerHTML=NAV.map(n=>`<button class="nav-item ${state.view===n[0]?'active':''}" data-action="goto:${n[0]}" ${state.view===n[0]?'aria-current="page"':''}>${icon(n[2])}<span>${n[1]}</span></button>`).join('');document.getElementById('breadcrumb').textContent=v[1];document.getElementById('page-title').innerHTML=`${v[1]}<span class="title-dot"></span>`;document.getElementById('eyebrow').textContent=v[3];document.getElementById('page-description').textContent=v[4];document.getElementById('period-label').textContent=PERIODS[state.period].label;document.querySelectorAll('[data-period]').forEach(b=>b.classList.toggle('selected',b.dataset.period===state.period));document.getElementById('direction-filter').value=state.dir;const pages={overview,projects,impact,capabilities,ecosystem,roadmap,updates:()=>window.CockpitUpdates?window.CockpitUpdates.renderPage():'<div class="panel empty-state">正在加载内容维护模块</div>'};document.getElementById('page-content').innerHTML=`<div class="view-fade">${pages[state.view]()}</div>`;if(window.enhanceDashboard)window.enhanceDashboard()}
let focusReturn=null;
function openOverlay(html,kind='modal'){if(!state.overlay)focusReturn=document.activeElement;state.overlay=kind;document.getElementById('overlay-root').innerHTML=`<div class="modal-scrim ${kind==='drawer'?'drawer-scrim':kind==='report'?'report-scrim':''}" data-scrim="true">${html}</div>`;document.body.style.overflow='hidden';const f=document.querySelector('#overlay-root .close-button,#overlay-root button');if(f)f.focus({preventScroll:true})}
function closeOverlay(){state.overlay=null;document.getElementById('overlay-root').innerHTML='';document.body.style.overflow='';if(focusReturn?.isConnected)focusReturn.focus({preventScroll:true})}
const modalHeader=(title,sub)=>`<div class="modal-top"><div><h2 id="dialog-title">${title}</h2><p>${sub}</p></div><button class="close-button" data-action="close" aria-label="关闭">×</button></div>`;
function projectDetail(id){const p=PROJECTS.find(p=>p.id===id);if(!p)return;openOverlay(`<section class="modal drawer" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${modalHeader(p.name,`${p.id} / ${DIRECTIONS[p.dir].name} / 演示项目`)}<div class="modal-content"><div style="display:flex;justify-content:flex-end;margin-bottom:14px"><button class="tag blue" data-manage-action="project:${p.id}">更新项目 ↗</button></div><div class="detail-title">目标 / WHY THIS PROJECT</div><p class="detail-body">${esc(p.goal)}</p><div class="detail-grid" style="margin-top:19px"><div class="detail-stat"><small>当前交付 · ${p.delivery}%</small><b>${p.deliveryLabel}</b></div><div class="detail-stat"><small>价值验证 · ${p.validation}%</small><b>${p.valueLabel}</b></div><div class="detail-stat"><small>项目状态</small>${tag(p.status)}</div><div class="detail-stat"><small>负责团队 / 目标日期</small><b style="font-size:12px">${esc(p.owner)} · ${esc(projectDate(p))}</b></div></div><div class="detail-title">历程 / MILESTONES</div><div class="timeline" style="padding:8px 4px">${p.history.map((h,i)=>`<div class="timeline-item"><div class="timeline-date">${h[3]||'2026'}.${h[0]} · ${h[1]}</div><h3>${h[2]}</h3></div>`).join('')}</div><div class="detail-title">当前成果 / OUTPUT</div><p class="detail-body">${esc(p.result)}</p><div class="detail-title">价值证据 / EVIDENCE</div><div class="detail-evidence"><b>证据级别：演示占位，未连接原始记录</b><br>${p.evidence}<br>正式接入需包含：来源、统计窗、样本、版本、更新时间和验收人。</div><div class="detail-title">当前卡点 / BLOCKER</div><div class="detail-issue">${esc(p.issue)}</div><div class="detail-title">下一步与待决策 / NEXT GATE</div><ul class="detail-list"><li>${esc(p.next)}</li><li>需要决定：${esc(p.decision)}</li></ul><div class="detail-title">关联对象 / CONNECTED WORK</div><div style="display:flex;gap:8px;flex-wrap:wrap">${ORGS.filter(o=>o.project===id).map(o=>`<button class="tag blue" data-action="org:${o.id}">${o.name} ↗</button>`).join('')}${ENTRANCES.filter(e=>e.project===id).map(e=>`<button class="tag gray" data-action="entrance:${e.id}">${e.name} ↗</button>`).join('')||tag('能力与服务场景','gray')}</div><div class="callout" style="margin-bottom:0">${DEMO_NOTICE}</div></div></section>`,'drawer')}
function orgDetail(id){let o=ORGS.find(o=>o.id===id);if(!o)return;openOverlay(`<section class="modal drawer" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${modalHeader(o.name+' · 合作档案',`${o.type} / ${o.id} / 匿名演示机构`)}<div class="modal-content"><div class="detail-title">合作范围 / SCOPE</div><p class="detail-body">${o.scope}</p><div class="detail-grid" style="margin-top:18px">${[['合作方式',o.mode],['交付阶段',o.stage],['商业阶段',o.commercial],['负责团队',o.owner]].map(x=>`<div class="detail-stat"><small>${x[0]}</small><b style="font-size:12px">${x[1]}</b></div>`).join('')}</div><div class="detail-title">合作历程 / HISTORY</div><div class="timeline" style="padding:6px 4px">${cooperationStages.slice(0,o.step+1).map((s,i)=>`<div class="timeline-item"><div class="timeline-date">阶段 0${i+1} · 演示记录</div><h3>${s}</h3><p>${i===o.step?'当前阶段；原型未绑定真实证据':'已完成的示意阶段；日期与原始记录待接入'}</p></div>`).join('')}</div><div class="detail-title">成效与价值验证 / IMPACT</div><p class="detail-body">${o.value}</p><div class="detail-title">问题 / NEXT ACTION</div><div class="detail-issue">${o.block}<br>下一动作：${o.next}</div>${window.CockpitUpdates?'<div class="detail-title">机构关键进展 / KEY EVENTS</div>'+window.CockpitUpdates.renderPlatformEvents(o.id):''}<div class="detail-title">商业证据 / COMMERCIAL EVIDENCE</div><div class="detail-evidence">合同：尚未接入<br>验收：尚未接入<br>开票与回款：尚未接入<br>未知保留为未知，待来源与责任人核对。</div><div class="detail-title">关联项目</div><button class="tag blue" data-action="project:${o.project}">${PROJECTS.find(p=>p.id===o.project).name} ↗</button><div class="callout">机构名称为匿名占位，所有关系与进度为结构演示。</div></div></section>`,'drawer')}
function entranceDetail(id){let e=ENTRANCES.find(e=>e.id===id);if(!e)return;openOverlay(`<section class="modal drawer" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${modalHeader(e.name+' · 上架档案',`${e.id} / ${e.type} / 演示入口`)}<div class="modal-content"><div class="detail-grid">${[['接入方式',e.protocol],['上架状态',e.status],['前台版本',e.version],['最近巡检',e.health]].map(x=>`<div class="detail-stat"><small>${x[0]}</small><b style="font-size:12px">${x[1]}</b></div>`).join('')}</div><div class="detail-title">上架核验清单</div><ul class="detail-list"><li>平台页面与正式访问地址：待接入</li><li>发布日期与前台版本：待核验</li><li>服务引擎与依赖版本：待接入</li><li>端到端任务验收：待绑定证据</li><li>事件回传与用户去重：${e.health}</li></ul>${window.CockpitUpdates?'<div class="detail-title">平台关键进展 / KEY EVENTS</div>'+window.CockpitUpdates.renderPlatformEvents(e.id):''}<div class="detail-title">用户与成效</div><p class="detail-body">独立观察该入口的用户身份、主动服务、任务完成与持续复用。尚未接入原始日志时保留缺失。</p><div class="detail-title">关联建设项目</div><button class="tag blue" data-action="project:${e.project}">${PROJECTS.find(p=>p.id===e.project).name} ↗</button><div class="callout">所有入口均为匿名演示。公开上架、机构合作与商业结果分别举证。</div></div></section>`,'drawer')}
function capDetail(index){const c=CAPABILITIES[Number(index)];if(!c)return;openOverlay(`<section class="modal drawer" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${modalHeader(c[0]+' · 能力域',`${c[4]} / 能力资产结构演示`)}<div class="modal-content"><div class="detail-grid">${[['MCP 能力',c[1]+' 项'],['Skills 方法',c[2]+' 项'],['Agents 服务',c[3]+' 项'],['资产状态',c[6]]].map(x=>`<div class="detail-stat"><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div><div class="detail-title">资产必备字段</div><ul class="detail-list"><li>唯一能力 ID、能力域、任务定义与版本</li><li>输入、输出、权限、依赖与适用边界</li><li>维护负责人、最近评测与最近成功使用</li><li>关联项目、入口、机构与用户任务</li><li>质量门槛、异常路径、退役与回滚策略</li></ul><div class="detail-title">证据状态</div><div class="detail-evidence">本原型只有能力域与数量示意。接入真实资产清单后，逐项关联评测、成功记录与维护责任。</div><div class="detail-title">关联项目</div><button class="tag blue" data-action="project:${c[5]}">${PROJECTS.find(p=>p.id===c[5]).name} ↗</button></div></section>`,'drawer')}
function help(){openOverlay(`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${modalHeader('数据口径与产品使用说明','方案原型 · 尚未连接业务系统')}<div class="modal-content"><div class="detail-issue">${DEMO_NOTICE} 本月、本季、全年按各自统计窗口展示；10 月与第四季度当前起始日相同，因此本月与本季的演示人数一致。不能据此判断真实业绩。</div><div class="detail-title">指标口径 / METRIC CONTRACT</div><div class="table-scroll"><table class="data-table"><thead><tr><th>指标</th><th>建议定义</th><th>统计实体</th></tr></thead><tbody>${[['到达用户','窗口内到达服务入口的去重用户','统一用户 ID'],['活跃用户','窗口内主动发起服务行为的去重用户','统一用户 ID'],['有效服务用户','窗口内至少完成一次定义明确的有效任务','用户 ID + 任务事件'],['7 日复用用户','已满 7 日观察期队列内再次完成有效任务','用户 ID + 队列'],['有效任务完成率','完成有效任务数 / 已发起有效任务数','任务 ID'],['服务一次成功率','首次尝试即成功的服务请求 / 全部服务请求','请求 ID'],['核心事件覆盖率','已验收核心事件 / 规划核心事件','事件定义 ID'],['身份可核对率','可映射统一用户 ID 的用户 / 可观测用户','身份映射记录'],['交付成熟度','定义→原型→联调→试点→上架→运营阶段映射','项目阶段'],['价值验证','需求→试用→完成→复用→业务结果阶段映射','证据阶段']].map(x=>`<tr><td class="table-title">${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td></tr>`).join('')}</tbody></table></div><p class="detail-body" style="margin-top:15px">阶段映射分值用于组合分布，不能解释为收益、成功率或真实百分比。规模、质量、价值和商业阶段独立保存；未观测值使用 null，禁止以 0 填补。</p><div class="detail-title">快照、周期与筛选</div><p class="detail-body">周期切换更新用户统计窗口，建设与资产显示截至当前快照的存量。方向筛选联动项目、能力、机构、入口和演示用户分组。当前快照与历史快照是独立记录，历史示例只展示归档结构，不伪造真实存档。</p><div class="detail-title">从原型接入业务数据</div><p class="detail-body">按战略方向、项目、里程碑、能力、机构、合作关系、入口、指标观察、证据和决策 10 类对象接入。每条指标需携带 source、window、entity、updated_at 和 completeness。演示页面的导出为结构参考，不含真实业务记录。</p><div style="display:flex;gap:12px;margin-top:22px;flex-wrap:wrap"><button class="primary-button" data-action="download">下载接入数据模板 <span>↓</span></button><button class="text-button" data-action="model">查看产品架构 ↗</button></div></div></section>`)}
function model(){openOverlay(`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${modalHeader('一套对象，多种汇报颗粒度','从管理层总览，到项目、机构与里程碑下钻')}<div class="modal-content"><div class="architecture">${[['01','战略方向','目标与资源优先级'],['02','产品 / 项目','交付与下一里程碑'],['03','能力 / 入口 / 机构','资产复用与合作关系'],['04','用户任务 / 结果','有效服务与价值证据']].map(x=>`<div class="architecture-box"><b>${x[0]} / ${x[1]}</b>${x[2]}</div>`).join('')}</div><p class="architecture-desc">所有视图使用同一套关联对象。管理层从方向、成果与待决策进入；产品团队追踪项目、依赖与验收；运营与合作团队下钻到用户队列、机构范围和入口效果。</p><div class="detail-title">六个视图，回答六个管理问题</div><ul class="detail-list">${[['战略总览','方向是否明确，当前最该推进什么'],['产品与项目','做了什么，交付与价值各在哪一阶段'],['用户与成效','谁在使用，是否完成任务并持续复用'],['能力体系','能力是否可发现、可交付、可维护'],['上架与合作','每个入口、每家机构走到哪一步'],['路线与决策','走过什么，卡在哪里，下一步如何验收']].map(x=>`<li><b style="font-weight:500">${x[0]}</b> · ${x[1]}</li>`).join('')}</ul><div class="callout"><b>数据连接关系</b> · 战略 → 目标 → 项目 → 里程碑与交付物 → 能力资产 → 机构与入口 → 用户任务 → 结果证据。证据、问题和决策可关联多个对象。</div><button class="primary-button" data-action="download">下载接入数据模板 <span>↓</span></button></div></section>`)}
function snapshots(){openOverlay(`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${modalHeader('汇报快照 · 冻结当时的判断','演示归档结构，不代表已有真实历史数据库')}<div class="modal-content"><div class="snapshot-row"><div>2026.10.27 · 当前演示快照<small>6 个视图 · 8 个项目 · 当前筛选：${state.dir==='all'?'全部方向':DIRECTIONS[state.dir].name}</small></div><span class="checkmark">当前查看</span></div><div class="snapshot-row"><div>2026.09.30 · 月末归档示例<small>待接入真实快照文件与来源</small></div><span class="tag gray">未接入</span></div><div class="snapshot-row"><div>2026.06.30 · 半年度归档示例<small>待接入真实快照文件与来源</small></div><span class="tag gray">未接入</span></div><div class="callout">正式系统按时点冻结指标、计划、状态与管理判断。后续的状态更新不覆盖历史，复盘时可比较原承诺与实际结果。</div><button class="primary-button" data-action="download">下载当前演示快照 <span>↓</span></button></div></section>`)}
function download(){const payload={meta:{type:'AI strategy cockpit integration template',is_demo:true,as_of:'2026-10-27',notice:DEMO_NOTICE,selected_period:state.period,selected_direction:state.dir},periods:PERIODS,report_modules:window.CockpitManagement?window.CockpitManagement.modules():[true,true,true,true,true,true,true],events:window.CockpitUpdates?window.CockpitUpdates.getEvents():[],directions:Object.entries(DIRECTIONS).map(([id,v])=>({id,...v})),projects:PROJECTS,milestones:PROJECTS.flatMap(p=>p.history.map((h,i)=>({id:`${p.id}-M${i+1}`,project_id:p.id,date:`2026.${h[0]}`,stage:h[1],description:h[2],evidence_id:null}))),capability_domains:CAPABILITIES.map((c,i)=>({id:`C0${i+1}`,name:c[0],mcp:c[1],skills:c[2],agents:c[3],project_id:c[5]})),institutions:ORGS.map(o=>({id:o.id,name:o.name,type:o.type})),cooperations:ORGS.map(o=>({id:`R-${o.id}`,institution_id:o.id,project_id:o.project,mode:o.mode,delivery_stage:o.stage,commercial_stage:o.commercial,contract_evidence:null,acceptance_evidence:null,payment_evidence:null})),entrances:ENTRANCES,metric_observation_template:{metric_id:'effective_service_users',value:null,unit:'user',source:null,window:{from:null,to:null},entity:'unified_user_id',updated_at:null,completeness:null,evidence_ids:[]},evidence_template:{id:null,source_url:null,observed_at:null,owner:null,verification_status:'unverified'},decisions:ISSUES};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='AI战略驾驶舱-演示数据与接入模板.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已下载演示数据与接入模板')}
function reportSlide(index){const d=periodData(),ps=currentProjects(),dir=state.dir==='all'?'全部方向':DIRECTIONS[state.dir].name;const slides=[
 {k:'01 / EXECUTIVE VIEW',title:'从能力与入口覆盖，走向可验证的业务价值。',sub:'本期重点是统一数据口径、形成服务闭环、推进机构验收。',cards:[['战略方向','三条主线协同推进','自营智能服务、开放能力与生态、共用治理底座，共同支撑持续服务。'],['本期判断','建设进展需要连接用户结果','重点验证主动使用、任务完成、持续复用与机构场景结果。'],['管理焦点','先打通关键路径','统一身份与事件，确认验收边界，按证据决定后续规模投入。']]},
 {k:'02 / PRODUCT & DELIVERY',title:'用统一项目档案，连接交付与价值验证。',sub:`当前筛选覆盖 ${ps.length} 个演示项目；阶段、状态、问题与下一步相互关联。`,cards:ps.slice(0,3).map(p=>[p.id+' / '+DIRECTIONS[p.dir].name,p.name,`${p.deliveryLabel} · 交付成熟度 ${p.delivery}%。下一步：${esc(p.next)}`])},
 {k:'03 / USERS & IMPACT',title:'服务是否发生，用户是否持续回来。',sub:'同一用户实体、同一统计窗口；7 日复用采用已满观察期的队列。',cards:[['有效服务用户',fmt(d.served),'窗口内至少完成一个有效任务的去重用户。'],['7 日复用用户',fmt(d.reused),'在满足观察期的有效服务用户中，再次完成任务。'],['有效服务占比',((d.active?d.served/d.active:0)*100).toFixed(1)+'%','有效服务用户 / 活跃用户；演示占比用于展示指标结构。']],numeric:true},
 {k:'04 / CAPABILITY & ECOSYSTEM',title:'把能力资产、上架入口与机构合作连起来。',sub:'能力、入口、合作方式与商业阶段各自管理，逐项关联证据。',cards:[['能力复用',relevantCaps().reduce((a,c)=>a+c[2],0)+' 项 Skills','按能力域连接项目、维护责任与最近成功记录。'],['外部入口',relevantEntrances().filter(e=>e.status==='生产上架').length+' 个生产上架','每个入口保存版本、验收、巡检与用户效果。'],['机构合作',relevantOrgs().length+' 家演示机构','逐家记录范围、交付阶段、商业阶段与下一动作。']],numeric:true},
 {k:'05 / ISSUES & DECISIONS',title:'把问题变成有责任、有期限的决定。',sub:'优先解决影响归因、验收与规模交付的关键依赖。',cards:ISSUES.filter(x=>state.dir==='all'||PROJECTS.find(p=>p.id===x.project).dir===state.dir).slice(0,3).map(x=>[x.severity+' / '+x.date,x.title,x.decision])},
 {k:'06 / ROADMAP & NEXT GATE',title:'用验收关口，决定下一阶段的投入。',sub:'建设、价值与治理共同进入阶段验收，逐步沉淀可复制的服务模式。',cards:[['11 月','闭环与验收','统一核心事件、完成重点任务与机构试点验收。'],['12 月','复用与复盘','复核持续使用、服务质量与可复用交付资产。'],['下一季度','规模与资源决策','根据任务结果、复用证据和机构反馈调整投入。']]}
 ];if(index===6)return `<article class="report-slide"><div class="slide-top"><span>AI STRATEGY / SELECTED EVENTS</span><span>${PERIODS[state.period].label} · ${dir}</span></div><div class="slide-kicker">07 / KEY PROGRESS</div><h1>平台关键进展与下一时间点。</h1><p class="slide-subtitle">根据内容维护中的类别与逐项勾选，生成本次汇报内容。</p>${window.CockpitUpdates?window.CockpitUpdates.reportHTML():''}<div class="slide-foot"><span>用户维护的事件快照 · 未接入真实系统</span><span>KEY PROGRESS / NEXT GATE</span></div></article>`;let s=slides[index];return `<article class="report-slide"><div class="slide-top"><span>AI STRATEGY / MANAGEMENT REVIEW</span><span>${PERIODS[state.period].label} · ${dir}</span></div><div class="slide-kicker">${s.k}</div><h1>${s.title}</h1><p class="slide-subtitle">${s.sub}</p><div class="slide-columns">${s.cards.map((x,i)=>`<div class="slide-card"><div class="slide-num">${x[0]}</div>${s.numeric?`<strong>${x[1]}</strong>`:`<h3>${x[1]}</h3>`}<p>${x[2]}</p></div>`).join('')}</div><div class="slide-foot"><span>设计原型 · 全部数字、状态与历程为演示</span><span>STRATEGY → DELIVERY → EVIDENCE</span></div></article>`}
function report(){const order=window.reportOrder?window.reportOrder():[0,1,2,3,4,5,6];const count=order.length;state.reportIndex=Math.max(0,Math.min(count-1,state.reportIndex));openOverlay(`<section class="report" role="dialog" aria-modal="true" aria-label="管理汇报模式"><div class="report-toolbar"><strong>AI 战略驾驶舱 <span style="color:#bec7d6;margin:0 10px">/</span> 管理汇报</strong><div class="report-controls"><span class="report-counter">${state.reportIndex+1} / ${count}</span><button data-manage-action="modules">选择内容</button><button data-action="print">导出 / 打印</button><button data-action="close">退出汇报 ×</button></div></div><div id="current-slide">${reportSlide(order[state.reportIndex])}</div><div class="report-bottom"><button data-action="reportprev" ${state.reportIndex===0?'disabled':''} aria-label="上一页">←</button><div class="report-dots">${order.map((v,i)=>`<button data-action="reportslide:${i}" class="${state.reportIndex===i?'current':''}" aria-label="第 ${i+1} 页" ${state.reportIndex===i?'aria-current="step"':''}></button>`).join('')}</div><button data-action="reportnext" ${state.reportIndex===count-1?'disabled':''} aria-label="下一页">→</button></div><div class="report-print-only">${order.filter((v,i)=>i!==state.reportIndex).map(reportSlide).join('')}</div></section>`,'report')}
let toastTimer;function toast(t){const e=document.getElementById('toast');e.textContent=t;e.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('visible'),3000)}
function go(view){if(!NAV.some(x=>x[0]===view))return;state.view=view;history.replaceState(null,'','#'+view);render();window.scrollTo({top:0,behavior:'instant'})}
function dispatch(action){const [type,value]=action.split(':');switch(type){case 'goto':go(value);break;case 'direction':state.dir=value;render();break;case 'project':projectDetail(value);break;case 'org':orgDetail(value);break;case 'entrance':entranceDetail(value);break;case 'cap':capDetail(value);break;case 'help':help();break;case 'model':model();break;case 'snapshots':snapshots();break;case 'close':closeOverlay();break;case 'download':download();break;case 'projectmode':state.projectMode=value;render();break;case 'ecotab':state.ecoTab=value;render();break;case 'orgmode':state.orgMode=value;render();break;case 'roadtab':state.roadTab=value;render();break;case 'caplevel':state.capLevel=value;render();break;case 'impactgrain':state.impactGrain=value;render();break;case 'issues':state.roadTab='issues';go('roadmap');break;case 'reportprev':state.reportIndex--;report();break;case 'reportnext':state.reportIndex++;report();break;case 'reportslide':state.reportIndex=Number(value);report();break;case 'print':printReport();break;}}
function printReport(){const reportElement=document.querySelector('.report');if(!reportElement)return;document.getElementById('current-slide').style.display='none';document.querySelector('.report-print-only').innerHTML=(window.reportOrder?window.reportOrder():[0,1,2,3,4,5,6]).map(reportSlide).join('');const restore=()=>{let e=document.getElementById('current-slide');if(e)e.style.display='';let p=document.querySelector('.report-print-only');if(p)p.innerHTML='';window.removeEventListener('afterprint',restore)};window.addEventListener('afterprint',restore);window.print();restore()}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a&&!a.disabled){dispatch(a.dataset.action);return}if(e.target.dataset.scrim)closeOverlay()});
document.addEventListener('change',e=>{if(e.target.id==='direction-filter'){state.dir=e.target.value;render()}if(e.target.id==='status-filter'){state.status=e.target.value;render()}if(e.target.id==='cooperation-filter'){state.orgModeFilter=e.target.value;render()}});
document.addEventListener('input',e=>{if(['project-search','org-search'].includes(e.target.id)){const id=e.target.id,cursor=e.target.selectionStart;if(id==='project-search')state.search=e.target.value;else state.orgSearch=e.target.value;render();const input=document.getElementById(id);input.focus({preventScroll:true});input.setSelectionRange(cursor,cursor)}});
document.querySelectorAll('[data-period]').forEach(b=>b.addEventListener('click',()=>{state.period=b.dataset.period;render()}));
document.getElementById('report-button').addEventListener('click',()=>{state.reportIndex=0;report()});
document.getElementById('help-button').addEventListener('click',help);document.getElementById('footer-help').addEventListener('click',help);document.getElementById('model-button').addEventListener('click',model);document.getElementById('snapshot-button').addEventListener('click',snapshots);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.overlay){closeOverlay();return}if(state.overlay==='report'&&!['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)){if(e.key==='ArrowRight'&&state.reportIndex<(window.reportCount?window.reportCount()-1:6)){e.preventDefault();state.reportIndex++;report()}if(e.key==='ArrowLeft'&&state.reportIndex>0){e.preventDefault();state.reportIndex--;report()}}if(e.key==='Enter'&&e.target.matches('tr[data-action],g[data-action]'))dispatch(e.target.dataset.action);if(e.key==='Tab'&&state.overlay){const items=[...document.querySelectorAll('#overlay-root button:not([disabled]),#overlay-root a,#overlay-root input,#overlay-root select,[role="dialog"] [tabindex="0"]')].filter(el=>el.getClientRects().length);if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(NAV.some(n=>n[0]===v)){state.view=v;render()}});
render();
